fn max(a: Vec<u64>) -> i64 {
    a.into_iter()
     .map(|u| u as i64)
     .max()
     .unwrap_or(-1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty() {
        assert_eq!(max(vec![]), -1);
    }

    #[test]
    fn all_small() {
        assert_eq!(max(vec![0, 5, 123, i64::MAX as u64]), i64::MAX);
    }

    #[test]
    fn mixed_small_and_large() {
        // 0x8000_0000_0000_0000 as u64 is 2^63, which as i64 is i64::MIN
        let data = vec![0, (i64::MAX as u64), (i64::MAX as u64) - 1, (i64::MAX as u64) + 1];
        // The +1 element casts to i64::MIN+1, which is still negative, so the max is i64::MAX
        assert_eq!(max(data), i64::MAX);
    }

    #[test]
    fn all_large() {
        // All values reinterpreted as negative; the one with the largest bit‐pattern
        // (i.e. the largest u64) becomes the least negative, hence the maximum.
        let data = vec![
            (i64::MAX as u64) + 2, // i64::MIN + 2
            (i64::MAX as u64) + 5, // i64::MIN + 5
            (i64::MAX as u64) + 1, // i64::MIN + 1
        ];
        // Among these, +5 is the least negative -> the signed max.
        assert_eq!(max(data), ( (i64::MAX as u64) + 5) as i64);
    }
}